def transform(grid):
    n = len(grid[0])
    center = next(i for i, value in enumerate(grid[0]) if value == 2)
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        if r <= center:
            out[r][center-r] = 2
            out[r][center+r] = 2
        if r < 3:
            continue
        lo = center-r+2 if r < center else 0
        hi = center+r-2 if r < center else n-1
        for c in range(max(0,lo), min(n,hi+1)):
            if (c-r) % 4 == 2 and out[r][c] == 0:
                out[r][c] = 1
    return out
